};
#pragma pack(pop)

C3DVector& C3DVector::AccurateNormalise()
{
    float x = X;
    float y = Y;
    float z = Z;
    float length = (float)sqrt(x * x + y * y + z * z);
    float inverse = 1.0f / length;
    X *= inverse;
    Y *= inverse;
    Z *= inverse;
    return *this;
}

